CREATE TABLE `service_requests` (`unique_key` BIGINT UNSIGNED NOT NULL PRIMARY KEY, `created_date` DATETIME(6) NULL, `closed_date` DATETIME(6) NULL, `due_date` DATETIME(6) NULL, `agency` VARCHAR(32) NULL, `complaint_type` VARCHAR(39) NULL, `borough` VARCHAR(32) NULL, `status` VARCHAR(32) NULL, `latitude` DOUBLE NULL, `longitude` DOUBLE NULL, `agency_name` VARCHAR(50) NULL, `descriptor` VARCHAR(80) NULL, `location_type` VARCHAR(36) NULL, `incident_zip` VARCHAR(32) NULL, `city` VARCHAR(32) NULL, `resolution_description` LONGTEXT NULL, `created_date_parse_error` TINYINT NOT NULL, `closed_date_parse_error` TINYINT NOT NULL, `due_date_parse_error` TINYINT NOT NULL, `closure_before_creation` TINYINT NOT NULL, `invalid_date_flag` TINYINT NOT NULL, `latitude_original` DOUBLE NULL, `longitude_original` DOUBLE NULL, `invalid_coordinates_original` TINYINT NOT NULL, `city_borough_imputed` TINYINT NOT NULL, `zipcode_city_imputed` TINYINT NOT NULL, `location_type_imputed` TINYINT NOT NULL, `latitude_imputed` TINYINT NOT NULL, `longitude_imputed` TINYINT NOT NULL, `status_updated` TINYINT NOT NULL, `invalid_coordinates` TINYINT NOT NULL, `missing_coordinates` TINYINT NOT NULL, `outside_nyc_bounds` TINYINT NOT NULL, `coordinate_quality_flag` TINYINT NOT NULL, `resolution_hours` DOUBLE NULL, `long_resolution_flag` TINYINT NOT NULL, `is_closed` TINYINT NOT NULL, `created_year` SMALLINT NULL, `created_month` SMALLINT NULL, `created_weekday` VARCHAR(32) NULL, `created_hour` SMALLINT NULL, INDEX idx_created(created_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;